{ pkgs }: {
    deps = [
        pkgs.carp
        pkgs.ispc
        pkgs.clang
        pkgs.gnumake
        pkgs.openblas
        pkgs.libffi
        pkgs.pkgconfig
    ];
    env = {
        CLANG_BIN = "${pkgs.clang}/bin/clang";
        ISPC_BIN = "${pkgs.ispc}/bin/ispc";
        CARP_BIN = "${pkgs.carp}/bin/carp";
        LD_LIBRARY_PATH = "${pkgs.libffi}/lib:${pkgs.openblas}/lib";
        C_INCLUDE_PATH = "${pkgs.openblas}/include";
    };
}

!/bin/bash
set e
ulimit s unlimited

ISPC_FLAGS="O3 target=avx2i32x8 opt=fastmath pic"
CFLAGS="O3 fPIC Wall Wnounusedfunction pthread mavx2 mfma"
LDFLAGS="lm pthread ldl"

rm rf out build
mkdir p out build src/include src/carp

ISPC_HEADER_FILE=src/include/kernels.h

echo "BUILD_STEP_1_COMPILING_ISPC_KERNELS"
ispc src/kernels.ispc $ISPC_FLAGS o build/kernels.o headeroutfile=$ISPC_HEADER_FILE

echo "BUILD_STEP_2_COMPILING_C_RUNTIME"
clang $CFLAGS I src/include c src/memory.c o build/memory.o
clang $CFLAGS I src/include c src/runtime.c o build/runtime.o

echo "BUILD_STEP_3_COMPILING_CARP_LOGIC"
carp src/carp/main.carp b optimize nocore logmemory

echo "BUILD_STEP_4_LINKING_FINAL_BINARY"
clang O3 o build/agi_core out/main.c build/kernels.o build/memory.o build/runtime.o $LDFLAGS

echo "BUILD_COMPLETE_EXECUTING_BINARY"
build/agi_core

CC = clang
ISPC = ispc
CARP = carp

CFLAGS = O3 fPIC Wall Wnounusedfunction pthread mavx2 mfma I./src/include
ISPCFLAGS = O3 target=avx2i32x8 opt=fastmath pic headeroutfile=src/include/kernels.h
LDFLAGS = lm pthread ldl

BUILD_DIR = build
SRC_DIR = src

all: $(BUILD_DIR)/agi_core

$(BUILD_DIR):
	mkdir p $(BUILD_DIR)

$(BUILD_DIR)/kernels.o: $(SRC_DIR)/kernels.ispc | $(BUILD_DIR)
	$(ISPC) $< $(ISPCFLAGS) o $@

$(BUILD_DIR)/memory.o: $(SRC_DIR)/memory.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) c $< o $@

$(BUILD_DIR)/runtime.o: $(SRC_DIR)/runtime.c | $(BUILD_DIR)
	$(CC) $(CFLAGS) c $< o $@

$(BUILD_DIR)/agi_core: $(BUILD_DIR)/kernels.o $(BUILD_DIR)/memory.o $(BUILD_DIR)/runtime.o $(SRC_DIR)/carp/main.carp
	$(CARP) $(SRC_DIR)/carp/main.carp b optimize nocore logmemory
	$(CC) O3 o $@ ./out/main.c $(BUILD_DIR)/kernels.o $(BUILD_DIR)/memory.o $(BUILD_DIR)/runtime.o $(LDFLAGS)

clean:
	rm rf $(BUILD_DIR) out src/include/kernels.h

ifndef MEMORY_H
define MEMORY_H

include <stddef.h>
include <stdint.h>
include <pthread.h>

define MAX_PERSISTENT_ARENAS 10
define ALIGNMENT 64

void mem_sys_init();
void mem_alloc_persist(size_t size, uint8_t arena_id);
void mem_alloc_temp(size_t size);
void mem_reset_temp();
size_t mem_get_total_usage();
void mem_free_all_persist(uint8_t arena_id);

endif

