(deftype Tensor [
    ptr (Ptr Float)
    rows Int
    cols Int
    size Int
])

(defmodule Tensor
    (defn createpersist [r c arenaid]
        (let [sz ( r c)
              bytes ( sz 4)]
            (Tensor.init (memallocpersist (Long.fromint bytes) arenaid) r c sz)))

    (defn createtemp [r c]
        (let [sz ( r c)
              bytes ( sz 4)]
