(load "src/carp/ffi.carp")

(deftype Tensor [
    ptr (Ptr Float)
    rows Int
    cols Int
    size Int
])

(defmodule Tensor
    (defn createpersist [r c arenaid]
        (let [sz ( r c)
              bytes ( sz 4)]
            (Tensor.init (memallocpersist (Long.fromint bytes) arenaid) r c sz)))

    (defn createtemp [r c]
        (let [sz ( r c)
              bytes ( sz 4)]
            (Tensor.init (memalloctemp (Long.fromint bytes)) r c sz)))

    (defn randnormal [r c mean std arenaid]
        (let [t (createpersist r c arenaid)]
            (do
                (rtrandnormal (Tensor.ptr t) (Long.fromint (Tensor.size t)) mean std)
                t)))

    (defn randuniform [r c min max arenaid]
        (let [t (createpersist r c arenaid)]
            (do
                (rtranduniform (Tensor.ptr t) (Long.fromint (Tensor.size t)) min max)
                t)))

    (defn zerograd [t]
        (rtzero (Tensor.ptr t) (Long.fromint (Tensor.size t))))

    (defn printdebug [t name]
        (rtprintstats (Tensor.ptr t) (Long.fromint (Tensor.size t)) (cstr name)))
)

(load "src/carp/tensor.carp")

(deftype AdamState [
    m Tensor
    v Tensor
    t Float
])

(defmodule Adam
    (defn create [params arenaid]
        (let [rows (Tensor.rows params)
              cols (Tensor.cols params)
              m (Tensor.createpersist rows cols arenaid)
              v (Tensor.createpersist rows cols arenaid)]
            (do
                (Tensor.zerograd m)
                (Tensor.zerograd v)
                (AdamState.init m v 1.0f))))

    (defn step [state params grads lr]
        (let [m (AdamState.m state)
              v (AdamState.v state)
              t (AdamState.t state)
              sz (Tensor.size params)]
            (do
                (adamupdate 
                    (Tensor.ptr params) 
                    (Tensor.ptr grads) 
                    (Tensor.ptr m) 
                    (Tensor.ptr v) 
                    lr 0.9f 0.999f 1e8f t sz)
                (AdamState.sett state (+ t 1.0f)))))
)

(load "src/carp/optimizer.carp")

(deftype Linear [
    weights Tensor
    biases Tensor
    gradw Tensor
    gradb Tensor
    optw AdamState
    optb AdamState
    cacheinput Tensor
])

(defmodule Linear
    (defn create [indim outdim arenaid]
        (let [w (Tensor.randnormal indim outdim 0.0f 0.02f arenaid)
              b (Tensor.createpersist 1 outdim arenaid)
              gw (Tensor.createpersist indim outdim arenaid)
              gb (Tensor.createpersist 1 outdim arenaid)
              ow (Adam.create w arenaid)
              ob (Adam.create b arenaid)
              cache (Tensor.createtemp 1 1)]
            (do
                (Tensor.zerograd b)
                (Linear.init w b gw gb ow ob cache))))

    (defn forward [layer input]
        (let [batch (Tensor.rows input)
              infeat (Tensor.cols input)
              outfeat (Tensor.cols (Linear.weights layer))
              w (Linear.weights layer)
              b (Linear.biases layer)
              out (Tensor.createtemp batch outfeat)]
            (do
                (Linear.setcacheinput layer input)
                (matmul_nn (Tensor.ptr input) (Tensor.ptr w) (Tensor.ptr out) batch infeat outfeat)
                (for [i 0 batch]
                    (let [offset ( i outfeat)]
                        (vecadd 
                            (Pointer.add (Tensor.ptr out) (Long.fromint offset)) 
                            (Tensor.ptr b) 
                            (Pointer.add (Tensor.ptr out) (Long.fromint offset)) 
                            outfeat)))
                out)))

    (defn backward [layer gradout]
        (let [input (Linear.cacheinput layer)
              w (Linear.weights layer)
              gw (Linear.gradw layer)
              gb (Linear.gradb layer)
              batch (Tensor.rows gradout)
              outfeat (Tensor.cols gradout)
              infeat (Tensor.cols input)
              gradinput (Tensor.createtemp batch infeat)]
            (do
                (matmul_tn (Tensor.ptr input) (Tensor.ptr gradout) (Tensor.ptr gw) infeat batch outfeat)
                (for [i 0 batch]
                    (let [offset ( i outfeat)]
                        (vecadd 
                            (Tensor.ptr gb) 
                            (Pointer.add (Tensor.ptr gradout) (Long.fromint offset)) 
                            (Tensor.ptr gb) 
                            outfeat)))
                (matmul_nt (Tensor.ptr gradout) (Tensor.ptr w) (Tensor.ptr gradinput) batch outfeat infeat)
                gradinput)))

    (defn update [layer lr]
        (do
            (Adam.step (Linear.optw layer) (Linear.weights layer) (Linear.gradw layer) lr)
            (Adam.step (Linear.optb layer) (Linear.biases layer) (Linear.gradb layer) lr)
            (Tensor.zerograd (Linear.gradw layer))
            (Tensor.zerograd (Linear.gradb layer))))
)

(load "src/carp/layer.carp")

(deftype AttentionHead [
    qproj Linear
    kproj Linear
    vproj Linear
    outputproj Linear
    cacheqk Tensor
    cachev Tensor
])

(defmodule AttentionHead
    (defn create [indim headdim arenaid]
        (AttentionHead.init
            (Linear.create indim headdim arenaid)
            (Linear.create indim headdim arenaid)
            (Linear.create indim headdim arenaid)
            (Linear.create headdim indim arenaid)
            (Tensor.createtemp 1 1) 
            (Tensor.createtemp 1 1)))

    (defn forward [head input]
        (let [batch (Tensor.rows input)
              q (Linear.forward (AttentionHead.qproj head) input)
              k (Linear.forward (AttentionHead.kproj head) input)
              v (Linear.forward (AttentionHead.vproj head) input)
              dimk (Tensor.cols q)
              scale (1.0f / (Double.sqrt (Float.fromint dimk)))
              qkscore (Tensor.createtemp batch batch)
              weights (Tensor.createtemp batch batch)
              out (Tensor.createtemp batch dimk)]
            (do
                (matmul_nt (Tensor.ptr q) (Tensor.ptr k) (Tensor.ptr qkscore) batch dimk batch)
                (vecscale (Tensor.ptr qkscore) scale (Tensor.ptr qkscore) (Tensor.size qkscore))

                (softmaxfwd (Tensor.ptr qkscore) (Tensor.ptr weights) batch batch)
                (AttentionHead.setcacheqk head weights)

                (matmul_nn (Tensor.ptr weights) (Tensor.ptr v) (Tensor.ptr out) batch batch dimk)
                (AttentionHead.setcachev head v)

                (Linear.forward (AttentionHead.outputproj head) out))))
)

(load "src/carp/layer.carp")
(load "src/carp/attention.carp")

(deftype TransformerBlock [
    norm1 LayerNorm
    attn AttentionHead
    norm2 LayerNorm
    ffn1 Linear
    ffn2 Linear
])

(deftype LayerNorm [
    gamma Tensor
    beta Tensor
    gradg Tensor
    gradb Tensor
    cachemean Tensor
    cacheinvstd Tensor
])

(defmodule LayerNorm
    (defn create [dim arenaid]
        (let [g (Tensor.createpersist 1 dim arenaid)
              b (Tensor.createpersist 1 dim arenaid)
              gg (Tensor.createpersist 1 dim arenaid)
              gb (Tensor.createpersist 1 dim arenaid)
              cm (Tensor.createtemp 1 dim)
              ci (Tensor.createtemp 1 dim)]
            (do
                (Tensor.randuniform g 1 dim 1.0f 1.0f) 
                (Tensor.zerograd b)
                (LayerNorm.init g b gg gb cm ci))))

    (defn forward [ln input]
        (let [batch (Tensor.rows input)
              dim (Tensor.cols input)
              out (Tensor.createtemp batch dim)]
            (do
                (layernormfwd (Tensor.ptr input) (Tensor.ptr (LayerNorm.gamma ln)) (Tensor.ptr (LayerNorm.beta ln))
                                (Tensor.ptr out) (Tensor.ptr (LayerNorm.cachemean ln)) (Tensor.ptr (LayerNorm.cacheinvstd ln)) 
                                batch dim)
                out)))
)

(defmodule TransformerBlock
    (defn create [dim heads arenaid]
        (let [attn (AttentionHead.create dim (Int.div dim heads) arenaid)
              n1 (LayerNorm.create dim arenaid)
              n2 (LayerNorm.create dim arenaid)
              f1 (Linear.create dim ( dim 4) arenaid)
              f2 (Linear.create ( dim 4) dim arenaid)]
            (TransformerBlock.init n1 attn n2 f1 f2)))

    (defn forward [block input]
        (let [normin (LayerNorm.forward (TransformerBlock.norm1 block) input)
              attnout (AttentionHead.forward (TransformerBlock.attn block) normin)
              res1temp (Tensor.createtemp (Tensor.rows input) (Tensor.cols input))]
            (do
                (vecadd (Tensor.ptr input) (Tensor.ptr attnout) (Tensor.ptr res1temp) (Tensor.size input))
                (let [norm2in (LayerNorm.forward (TransformerBlock.norm2 block) res1temp)
                      ffn1out (Linear.forward (TransformerBlock.ffn1 block) norm2in)
                      actout (Tensor.createtemp (Tensor.rows ffn1out) (Tensor.cols ffn1out))]
                    (do
                        (gelufwd (Tensor.ptr ffn1out) (Tensor.ptr actout) (Tensor.size ffn1out))
                        (let [ffn2out (Linear.forward (TransformerBlock.ffn2 block) actout)
                              finalout (Tensor.createtemp (Tensor.rows ffn2out) (Tensor.cols ffn2out))]
                            (do
                                (vecadd (Tensor.ptr res1temp) (Tensor.ptr ffn2out) (Tensor.ptr finalout) (Tensor.size finalout))
                                finalout)))))))
)

(load "src/carp/transformer.carp")

(deftype AGIModel [
    inputlayer Linear
    block1 TransformerBlock
    block2 TransformerBlock
    outputlayer Linear
])

(defmodule AGIModel
    (defn create [dim blocks heads arenaid]
        (AGIModel.init
            (Linear.create 1 dim arenaid)
            (TransformerBlock.create dim heads arenaid)
            (TransformerBlock.create dim heads arenaid)
            (Linear.create dim 10 arenaid)))

    (defn forward [model input]
        (let [h0 (Linear.forward (AGIModel.inputlayer model) input)
              h1 (TransformerBlock.forward (AGIModel.block1 model) h0)
              h2 (TransformerBlock.forward (AGIModel.block2 model) h1)
              out (Linear.forward (AGIModel.outputlayer model) h2)
              finalout (Tensor.createtemp (Tensor.rows out) (Tensor.cols out))]
            (do
                (softmaxfwd (Tensor.ptr out) (Tensor.ptr finalout) (Tensor.rows out) (Tensor.cols out))
                finalout)))

    (defn update [model lr]
        (do
            (Linear.update (AGIModel.inputlayer model) lr)
            (Linear.update (AGIModel.outputlayer model) lr)
            ))
)

(load "src/carp/agi.carp")

(defn main []
    (do
        (rtinit)
        (println "AGI_SYSTEM_BOOT_SEQUENCE_INITIATED")

        (let [batchsize 32
              seqlen 16
              dim 256
              blocks 2
              heads 8
              arenamodel 10
              arenadata 11
              epochs 1000
              lr 0.0001f]

            (let [model (AGIModel.create dim blocks heads arenamodel)
                  inputs (Tensor.randnormal batchsize dim 0.0f 1.0f arenadata)
                  targets (Tensor.randuniform batchsize 10 0.0f 1.0f arenadata)

                  lossval (Tensor.createpersist 1 1 arenamodel)
                  gradloss (Tensor.createpersist batchsize 10 arenamodel)]

                (println "AGI_MODEL_LOADING_COMPLETE")

                (for [i 0 epochs]
                    (do
                        (let [preds (AGIModel.forward model inputs)]
                            (do
                                (mseloss (Tensor.ptr preds) (Tensor.ptr targets) (Tensor.ptr gradloss) (Tensor.ptr lossval) (Tensor.size preds))

                                (if (= (mod i 50) 0)
                                    (Tensor.printdebug lossval (String.concat ["EPOCH_" (String.fromint i) "_LOSS"]))
                                    ())

                                (AGIModel.update model lr) 
                            ))
                        (memresettemp)
                        (if (= (mod i 500) 0) (rtsleep_ms 10) ())
                    )
                )

                (println "AGI_TRAINING_CYCLE_TERMINATED")
                (memfreeall_persist arenamodel)
                (memfreeall_persist arenadata)
            )
    )))
